T=[]
def task(id,title,p,group,questions,answer,points,**kw):
    t=dict(id=id,title=title,lesson=1 if p<10 else 2,range=[p],focus=[p],order=p,group=group,questions=questions,source=f'课本旁注 第{p}段',role='我们做',mode='oral',keywords=['为什么','有什么不同','哪些','作用','用意'],guide='先想一想，口头回答，再展开讲评。',hints=['留意题目问谁、问什么。',f'回看第{p}段，用具体词句说明。'],answer=answer,points=points,scores=[1]*len(points),explain=answer,reject='只报词语而没有结合本段解释，不够完整。',evidenceQuotes=[],skill='语境理解',processing='定位、筛选与解释',accept='接受保留相同意思的表达。',boundary='判断只限于课文所写情境。',minutes=3)
    t.update(kw);T.append(t);return t
def check(id,q,opts,c,why):return dict(id=id,question=q,options=opts,correct=c,why=why)
def ev(label,ps,terms,required=None):
    d=dict(label=label,p=ps,terms=terms)
    if required:d['requiredTerms']=required
    return d
def field(id,label,placeholder):return dict(id=id,label=label,placeholder=placeholder)

task('missed-calls','第一段：先留下一个疑问',1,1,['“我”为什么没接妈妈的电话？'],
'第1段只写“我”太投入、没有注意时间，以及发现未接来电；电话为什么没接的完整说明，要读到第3段再核对。先保留疑问，不把猜想当成事实。',[],source='教参 第1段（先存疑，第3段核对）',guide='先口头提出可能原因。读到第三段，再检查猜想。',hints=['本段已经告诉我们哪些事？','找“太投入”和“没有注意时间”；接电话的具体原因稍后核对。'],evidenceQuotes=[P[0]],reject='不能在只读第1段时，把“故意不接”当作事实。',boundary='第1段未交代静音模式；不提前把第3段的解释当作已读信息。',minutes=2)
task('fear-return','第二段：为什么害怕',2,1,['“我”为什么会“战战兢兢”？'],
'“我”很晚才回家，又没接妈妈的来电，担心受到父母责备，因此开门时十分害怕。',['晚归且未接来电','担心父母责备'],range=[1,2],mode='objective',role='我做',guide='先找已经读到的事实，再判断“我”担心什么。',
checks=[check('fear','哪一项解释最有依据？',['作业没完成，害怕老师责备','晚归又漏接，担心父母责备','钥匙打不开，担心家中无人','父亲没吃饭，担心受到追问'],1,['本段没有作业未完成或老师责备的信息。','第1段的晚归与未接电话，能解释第2段开门时的害怕。','钥匙已打开门；家中无人也没有依据。','爸爸问的是“我”吃晚餐没有，不能换成父亲。'])],hints=['把开门前的事与开门时的心情连起来。','回看第1段的时间和来电，再看第2段父母的反应。'],evidenceQuotes=[P[0], '到了家门口，我战战兢兢地插入钥匙，“咔嚓”一声，开了。'],explain='晚归、漏接电话是直接信息；担心被责备是有依据的推断。',reject='只解释“战战兢兢＝害怕”，没有回答为什么。',skill='原因推断',minutes=4)
task('parents-return','第二段：两人的反应',2,1,['“我”很晚回家，妈妈和爸爸的反应有什么不同？'],
'妈妈紧皱眉头、表情严肃，一脸不悦地责问“我”；爸爸两眼布满血丝、神色焦虑，先安抚妈妈，再关心地询问“我”晚归的原因和是否吃了晚餐。',['妈妈的表情与责问','爸爸的焦虑、安抚与关心'],mode='objective',guide='分别找妈妈、爸爸的原句，可以各加入多句。',evidence=[ev('妈妈的反应',[2],['妈妈紧皱','不悦'],['紧皱眉头','责问']),ev('爸爸的反应',[2],['爸爸则','爸爸连忙'],['焦虑','关心'])],checks=[check('contrast','两人的不同反应是什么？',['妈妈担心作业，爸爸担心晚餐','妈妈耐心倾听，爸爸严厉责问','妈妈急着休息，爸爸等我解释','妈妈严肃责问，爸爸温和关心'],3,['妈妈责问的是晚归和不接电话，不是作业。','人物反应被调换，且妈妈没有耐心倾听。','文中没有妈妈急着休息的信息。','妈妈责问，爸爸安抚妈妈并关心“我”，差异明确。'])],hints=['比较两人面对同一件事时怎样说、怎样做。','妈妈“责问”；爸爸“拍拍”“关心地问”。两人的表情也要留意。'],evidenceQuotes=[P[1]],explain='先比较表现，读完全篇后再概括人物特点。不能把爸爸温和等同于不重视规矩。',reject='只写“妈妈生气、爸爸不生气”过于简单；不能说爸爸不在乎“我”。',skill='比较信息',minutes=5)
task('hurt-response','第三段：行为写出心情',3,1,['第3段在描写“我”时运用了哪些人物描写？有什么作用？'],
'运用了行动描写和心理描写。“一句话也不说”“快步走进房间”“重重地把门关上”等行动，结合心里想要自由、认为妈妈不讲理的想法，表现“我”想解释却不被倾听时的难过、委屈和生气。',['行动描写及证据','心理描写及证据','解释委屈、生气的具体原因'],mode='subjective',role='你做',guide='各找一处原句，再用一两句话解释心情。',conceptNotes=[['行动描写','写人物怎样做。例：“快步走进房间”。'],['心理描写','写人物心里的想法。例：“为什么不能给我多一点儿自由？”']],evidence=[ev('行动原句',[3],['快步','重重']),ev('心里想法的原句',[3],['自由','不讲理'])],fields=[field('effect','描写方法和作用','用了什么描写？写出“我”怎样的心情？为什么？')],hints=['一处看人物怎样做，一处看人物心里怎样想。','把“快步”“重重”与“委屈”“自由”“不讲理”联系起来。'],oral=[['现在能核对“我”为什么没接电话了吗？','第3段明确写手机设成静音模式；做作业太投入又忘了时间。不能说“我”故意不接电话。']],evidenceQuotes=[P[2]],explain='作用不能只写“生动形象”；须说清人物的心情及造成这种心情的处境。“不讲理”是“我”当时的看法。',reject='把心里想的话当成实际说出口的对话；把“不讲理”当成作者对妈妈的最终客观判断。',skill='描写与作用',minutes=7)
task('cold-war','第四段：冷战中的词语',4,2,['“和事佬”和“举白旗”分别是什么意思？'],
'“和事佬”指调解争执、促使双方和好的人，文中指爸爸。“举白旗”本来指投降认输，文中指“我”先认错、向妈妈道歉。',['和事佬的意思与所指','举白旗的意思与语境'],mode='objective',guide='联系爸爸和“我”在冷战中的做法，选择正确解释。',checks=[check('peace','文中的“和事佬”指什么？',['调解双方矛盾、盼望和好的人','替孩子找理由、支持顶嘴的人','判断谁最有理、宣布输赢的人','避免谈论争执、转开话题的人'],0,['爸爸努力让母女和好，符合调解争执的意思。','没有爸爸支持顶嘴的信息。','调解重在和好，不是宣布输赢。','爸爸积极劝和，不是回避争执。']),check('flag','“不想先举白旗”指什么？',['不想先去海边玩放风筝','不想先请爸爸停止劝说','不想先向妈妈认错道歉','不想先交还放风筝工具'],2,['去海边是后来的事，不是此处含义。','“举白旗”指认输认错，不是劝爸爸停止。','联系后句“凭什么要我先道歉”，此义明确。','不能按风筝情节或字面物件理解。'])],hints=['这些词不是在说真的旗子或职业。','看爸爸“希望我们和好”，再看“凭什么要我先道歉”。'],evidenceQuotes=[P[3]],explain='“分别”要求两个词都解释，再联系各自在本文中的对象与行为。',reject='只按字面解释举起白色旗子；把和事佬说成偏袒某一方。',skill='词语语境义',minutes=4)
task('awkward-trip','第八段：为什么别扭',8,2,['“我”听到妈妈也一起去放风筝时，为什么心里有些别扭？'],
'“我”和妈妈还在冷战，虽然有歉意，却不愿先道歉；得知要与妈妈同行，“我”不知道该如何与她相处，因而不自在。',['冷战未结束','不愿先认错却要同行，感到不自在'],range=[4,8],guide='先读完第五至八段，再回看第四段。',hints=['“别扭”不只是“不开心”，要联系两人的关系。','第4段写歉意和不肯先道歉；第7段突然说妈妈也去。'],evidenceQuotes=[P[3],P[6],P[7]],explain='第五至九段短段依次阅读；第8段只用已读内容解释，不提前讨论海边的转变。',reject='不能说“我”不喜欢放风筝；第6段已写答应同行。',skill='结合前文解释心情',minutes=3)
task('mixed-feelings','第十段：五味杂陈',10,3,['“五味杂陈”是什么意思？“我”为什么会有这样的心理？'],
'“五味杂陈”形容多种感受交杂、难以说清。“我”为晚归的事与妈妈冷战，心里有歉意，也想和好，却又觉得妈妈也有错、不愿先认错，因此不知道该不该开口与妈妈说话。',['词义：多种感受交杂','歉意、想和好的心情','觉得妈妈也错，不愿先认错的矛盾'],range=[4,10],mode='objective',guide='把两种相反的想法合起来理解。',evidence=[ev('眼前的犹豫',[10],['该不该'])],checks=[check('mixed','哪项最能解释“我”的矛盾心情？',['想回家做作业，却担心爸爸反对','想请妈妈帮忙，却担心风筝断线','想跟爸爸交谈，却担心妈妈听到','想与妈妈和好，却不愿先行认错'],3,['本段没有回家做作业的想法。','风筝还未断线，不能用后来结果解释此时心情。','课文没有“担心妈妈听到”的信息。','第4段的歉意、不愿道歉，与第10段该不该说话互相印证。'])],hints=['这不是一种单纯的情绪，而是相互拉扯的感受。','回看第4段“歉意”“妈妈也有错”，再看第10段“该不该”。'],evidenceQuotes=[P[3],P[9]],explain='教参将“想和好”视为结合歉意、犹豫而作出的合理推断；不要仅写“又高兴又难过”而没有具体内容。',reject='只说“心情复杂”，没有解释为何复杂；用断线后的惊慌解释断线前的心理。',skill='多点整合与语境解释',minutes=5)
task('kite-simile','第十一段：像个不听话的孩子',11,4,['第11段运用了什么修辞手法来描写风筝？'],
'“风筝却像个不听话的孩子”主要运用比喻，把风筝比作不听话的孩子，生动写出风筝不受控制、挣脱牵引的样子。“用力挣脱”也带有拟人色彩。读到第13段时，再联系爸爸说的话。',['比喻及本体、喻体','不受控制、挣脱牵引的具体特点'],source='教参 第11段；作用为教师补充追问',conceptNotes=[['比喻','用相似的事物打比方。如“汗珠像豆子”。'],['拟人','把事物当人来写。如“花儿向我点头”。']],guide='先比较两个例子，再解释风筝句。',hints=['看“像个……”把什么与什么相比。','本体是风筝，喻体是不听话的孩子；共同点是什么？'],evidenceQuotes=['我连忙把风筝线往回拉，想不到风筝却像个不听话的孩子，用力挣脱。'],explain='以完整句“像个不听话的孩子”判断，比喻最明确；若学生从“用力挣脱”谈拟人，教师应先核对其解释，不机械判错。',reject='只报“比喻”而追问时说不出比作什么、突出什么；把修辞当成风筝真的有思想。',skill='修辞及具体表达作用',boundary='风筝与孩子的联系在第13段再整合，不提前灌输结尾。',minutes=4)
task('mother-sun','第十二段：怕晒仍然出门',12,5,['妈妈最不喜欢晒太阳，为什么还会提议出来放风筝？'],
'妈妈关心“我”，知道“我”考试压力大，希望借放风筝帮助“我”解压；所以即使自己怕晒太阳、担心长斑，也愿意主动提议出门。结合她整理风筝、微笑和捡风筝的行为，还可推想她希望改善母女关系。',['关心考试压力，希望帮助解压','为孩子的需要暂时放下自己的顾虑','希望改善关系：结合前后行为作合理推断'],mode='subjective',role='你做',guide='先写原文明说的原因，再说明妈妈这样做反映什么。',evidence=[ev('妈妈提议出游的直接原因',[12],['压力大','解压'])],fields=[field('reason','原因与解释','妈妈知道……，希望……，因此即使……也……。')],hints=['区分爸爸说出的原因与我们进一步推想的心意。','找“考试压力大，需要解压”；再比较妈妈怕晒太阳的顾虑。'],evidenceQuotes=[P[11]],explain='帮助解压是原文明说的原因；希望改善关系是教参提示的合理推断，可接受但不要求当作唯一必答事实。',reject='只写“妈妈爱我”而无具体需要；断言妈妈因知道风筝会断线才来；把自己想出来的原因当明示事实。',skill='原因、取舍与推断边界',scores=[1,1,1],minutes=6)
task('father-intent','第十三段：爸爸的用意',13,6,['第13段中，爸爸对“我”说的话有什么用意？'],
'爸爸借风筝挣脱线后无法高飞的情形，让“我”明白父母的管教包含关心和引导。孩子可能觉得受到约束，但若一味排斥合理的提醒，就可能缺少判断和规则意识而走弯路。爸爸希望“我”体谅父母的苦心。',['借风筝情形作比','解释合理管教的保护与引导','希望孩子体谅父母'],guide='先说风筝发生了什么，再说爸爸想让孩子明白什么。',hints=['“用意”问爸爸想让“我”明白什么，不只问风筝结局。','把“线的牵引”与父母的引导联系，把“挣脱后无法高飞”与缺少引导联系。'],evidenceQuotes=[P[12]],explain='这是爸爸借眼前的事劝导孩子。理解他的用意，不等于必须认同父母每一种管教方式。',reject='只回答风筝断了不能飞；或扩大为孩子必须无条件服从、任何自由都会导致失败。',skill='句子含义与说话用意',boundary='本文表达父母的爱与引导，不证明所有管教正确或严格越多越好。',minutes=5)
task('awakening','第十四段：明白了什么',14,7,['“如梦初醒”是什么意思？','说说你对“孩子不就是父母手中的风筝吗”这句话的看法。'],
'“如梦初醒”比喻原来糊涂或不明白，后来突然醒悟。这里指“我”听了爸爸的话，理解父母的约束中有爱和引导。孩子与风筝的比喻突出适当引导的帮助；也可指出孩子有自己的想法，父母需要倾听、沟通，给孩子练习自主判断的空间。',['词义：突然醒悟','语境：理解父母的苦心','看法有理由，不把比喻无限扩大'],source='教参 第14段（词义与看法）',mode='objective',guide='先选出“我”明白的事，再口头说说你的看法和理由。',checks=[check('wake','“如梦初醒”在本文中指什么？',['发现做作业晚归会影响成绩','明白父母约束中有爱与引导','懂得风筝断线以后还能高飞','确认妈妈同意以后不用报备'],1,['成绩不是爸爸这番话的重点。','联系第13段的劝导，理解关心与引导才贴合语境。','风筝断线后落进树丛，并非还能高飞。','原文没有妈妈作出这种承诺。'])],oral=[['这个比喻有哪些道理？又有哪些需要补充？','可赞同适当引导有助成长，也可补充孩子需要自主判断，父母要沟通。须解释理由，不能只复述“孩子像风筝”。']],hints=['此处没有真的睡觉或做梦。','回看第13段，爸爸把什么比作风筝线的牵引？'],evidenceQuotes=[P[13],P[12]],explain='词义点选检查语境理解；口头看法由教师根据理由核对，不由选择结果代替。',reject='解释为从睡梦中醒来；说故事已经明确写出“我”向妈妈道歉。',boundary='课文止于醒悟，没有写出道歉、拥抱或冷战正式结束。',skill='词义、主题与评价',minutes=4)
task('expand-sentence','全文读完：扩写句子',14,8,['扩写句子。','我看着电视。'],
'示例：我蜷着双腿坐在沙发上，目不转睛地看着电视里的球赛。扩写保留“我看电视”的原意，补入合理的动作、姿态或专注程度，使画面更具体。',['保留人物与原有动作','补充合理细节，句意通顺'],lesson=2,order=17,source='课本《巩固练习》第一题',mode='subjective',role='你做',guide='先看课本例句怎样增加细节，再自己扩写一句。',conceptNotes=[['原句','妈妈解着风筝线。'],['扩写','妈妈弯着腰，聚精会神地解着缠绕在树丛中的风筝线。'],['试一试','谁？怎样做？看什么？只加能帮助读者看见画面的内容。']],fields=[field('expanded','我的扩写','我……看着……。')],evidenceQuotes=['妈妈弯着腰，聚精会神地解着缠绕在树丛中的风筝线，额头上都是豆大的汗珠。'],hints=['保留“我看着电视”这件事。','可以补姿态、专注程度或电视内容，不必每项都加。'],explain='先找句子主干，再补合适修饰语。字数多不等于写得好；避免“认真地仔细地专心地”重复堆叠。',reject='改变为玩手机；动作矛盾；只堆近义词而没有具体画面。',skill='句子扩写',minutes=5)
task('family-comparison','全文：比较爸爸和妈妈',14,9,['从文中画出描写爸爸和妈妈的句子，通过比较把握人物特点，理解文章主题。'],
'晚回家时：爸爸神色焦虑，安抚妈妈并询问“我”是否吃了晚餐，说明他关心孩子、脾气温和；妈妈紧皱眉头、一脸不悦地责问，说明她面对晚归和失联时较严厉、急切。放风筝时：爸爸慈爱地说明妈妈的提议，搂着“我”借风筝讲道理，说明他温和、善于引导；妈妈怕晒仍提议出门，整理、捡拾风筝并专心解线，说明她以实际行动关心孩子。父母表达爱的方式虽然不同，但都是出于对孩子的爱，希望孩子健康成长。',['晚归：爸爸的特点与依据','晚归：妈妈的特点与依据','放风筝：爸爸的特点与依据','放风筝：妈妈的特点与依据','比较后概括共同的爱与成长愿望'],lesson=3,order=18,range=[1,14],focus=[2],source='课本《巩固练习》第二题',mode='subjective',role='你做',concept='character',guide='逐项回看原文，自己写特点，再用行为说明。',evidence=[ev('晚归时：描写爸爸与妈妈的原句',[2],['妈妈','爸爸']),ev('放风筝时：描写爸爸与妈妈的原句',[10,11,12,13],['爸爸','妈妈'])],fields=[field('return','晚归时：爸爸与妈妈','爸爸……，依据……；妈妈……，依据……。'),field('kite','放风筝时：爸爸与妈妈','爸爸……，依据……；妈妈……，依据……。'),field('theme','共同点与主题','表达爱的方式虽然不同，但都……。')],hints=['比较同一情境，不要只给人物贴标签。','晚归看第2段；放风筝看第10—13段，说明具体做法为何体现特点。'],evidenceQuotes=[P[1],P[11],P[12]],explain='课本将表情、神色和汗珠归入“外貌描写”；课堂沿用课本口径，可说明其中包含神态细节。人物特点须用所选证据解释，允许等义概括。',reject='不接受“妈妈不爱孩子”“爸爸没有原则”等缺乏依据的极端评价；不因一个人物概括不全就清零其他独立要点。',skill='跨段比较、人物特点与主题',boundary='区别“我”第3段认为妈妈不讲理与全文对母爱的理解。',minutes=18)
task('freedom-guidance','全文：自由与管教',14,10,['在家庭教育方面，有人认为应该给孩子自由；有人则认为应该对孩子严加管教。你对此有什么看法？'],
'示例：我认为应给予孩子适当自由，并通过沟通订立合理界限。孩子需要练习独立判断，但也可能忽略安全与责任。例如文中的“我”做作业忘了时间，还漏接电话，使父母担心。如果亲子事先商量回家时间，遇到变化及时报平安，孩子便能自主完成小组作业，父母也能了解情况。可见，自由与管教可以互相配合，重点是理解需要、说明理由，并逐渐学会负责。',['立场明确，回应自由与管教','理由说明需要、限制或影响','例子具体，人物和情境清楚','解释例子怎样支持立场并回扣'],lesson=3,order=19,range=[1,14],focus=[14],source='课本《巩固练习》第三题',mode='subjective',role='你做',required=True,conceptNotes=[['立场','我怎么看？'],['理由','为什么？'],['例子','什么事能说明？'],['回扣','例子怎样支持我的看法？']],guide='写一段完整回答。可以采用课文、生活中的例子，或明确标为“假设”的情境。',fields=[field('position','立场','我认为……。'),field('reason','理由：为什么','因为……。'),field('example','具体例子','例如……。'),field('link','回扣：例子怎样支持看法','这说明……，所以……。')],hints=['“自由”不等于不负责任；“管教”也要说明内容与方式。','例子写出具体情境、做法及影响，再解释为何支持你的立场。'],evidenceQuotes=[P[0],P[1],P[12]],explain='没有唯一立场。教师核对理由、例子与立场的关系。不要用“因为很好”循环解释，也无须披露家庭隐私。',reject='只选立场；只说父母为你好；例子与观点无关；把“严加管教”直接等同于越严越有效。',alternatives=['也可主张更多自主空间：须说明孩子已有的能力、自由的范围及怎样承担后果。','也可主张某些方面较严格：如安全或失联问题，说明合理界限、沟通与后续调整，不能以侮辱或伤害作为有效管教的依据。'],skill='开放评价与有依据表达',boundary='示范中的报平安协议是假设建议，不是课文已经发生的情节。',minutes=17)

L=dict(id='2hcl-u1-fang-feng-zheng',version='20261019-ffz-1',sequenceVersion=1,title='放风筝',label='中二高级华文 · 单元一',author='本文改编自羊牧的《放风筝》。',paragraphs=P,paragraphIdeas=ideas,panels=mapping,panelRects=rects,idioms=[],tasks=T,objectives=['结合前后文，解释“我”从委屈、别扭到醒悟的心理变化。','从语言、行动与外貌描写取证，比较爸爸和妈妈表达爱的方式。','结合语境解释风筝的比喻与爸爸说话的用意，并学会扩写具体句子。','以立场、理由、例子和回扣，完成对自由与管教的有依据回应。'])
(D/'content.js').write_text('window.LESSON='+json.dumps(L,ensure_ascii=False,indent=2)+';\n')
lex={
'投入':'全心放在一件事上。','未接来电':'有电话打进来，但没有接听。','战战兢兢':'因害怕而小心谨慎、紧张不安的样子。','钥匙':'开锁或锁门的工具。','紧皱眉头':'眉头紧紧皱起，显出担心或不满。','严肃':'神情认真、不带笑容。','血丝':'眼睛里显出的细小血管。','焦虑':'着急、担忧而不安。','不悦':'不高兴。','责问':'带着责备的语气询问。','安抚':'使情绪不安的人平静下来。','责备':'指出别人的过错并加以批评。','干脆':'索性，直接采取某种做法。','委屈':'觉得自己受到误解或不公平对待而难过。','更何况':'进一步提出更有力的理由。','静音模式':'手机不发出来电等提示声音的设置。','冷战':'这里指家人争执后互不理睬。','和事佬':'调解争执，促使双方和好的人。','歉意':'觉得对不起别人而产生的心情。','举白旗':'本指投降认输，这里指先认错道歉。','温和':'说话或态度不急躁、不严厉。','无聊':'没有感兴趣的事情可做，觉得没意思。','别扭':'这里指心里不自在，相处时不自然。','回应':'对别人说的话作出回答或反应。','五味杂陈':'多种感受交杂在一起，难以说清。','整理':'使东西有条理、便于使用。','摇摇晃晃':'左右或上下摆动、不稳定的样子。','尴尬':'这里指因关系不自然而感到不好意思。','挣脱':'用力摆脱束缚。','树丛':'聚集生长在一起的树木。','提议':'提出想法，供大家考虑。','慈爱':'长辈对晚辈温柔而关爱的态度。','解压':'减轻心理压力。','惊讶':'对出乎意料的事情感到吃惊。','长斑':'皮肤上出现颜色较深的斑点。','主动':'不等别人要求，自己愿意去做。','聚精会神':'把精神和注意力高度集中起来。','缠绕':'条状物盘绕或绕住其他东西。','豆大':'像豆子一般大，用来突出汗珠明显。','搂':'用胳膊围住或抱住。','如梦初醒':'好像刚从梦中醒来，比喻原来不明白，后来突然醒悟。'}
words={w:{'meaning':m,'en':''} for w,m in lex.items()}
assert all(any(w in p for p in P) for w in words)
(D/'lexicon.js').write_text('window.LESSON_WORDS='+json.dumps(words,ensure_ascii=False,indent=2)+';\nwindow.WORD_ALIASES={};\nwindow.HWT_WORD_CONTEXT=()=>({lessonId:window.LESSON.id,lessonTitle:window.LESSON.title,grade:2,unit:1,paragraphs:window.LESSON.paragraphs});\nwindow.HWT_WORD_LEXICON=()=>window.LESSON_WORDS;\n')
for i in range(1,4):
    original=ROOT.parent/f'upload/放风筝-{i}.png'
    if original.exists():shutil.copyfile(original,D/f'assets/comic{i}.png')
    else:assert (D/f'assets/comic{i}.png').exists(), 'Original comic asset missing'
(ROOT/'tools/fang-feng-zheng/lesson.json').write_text(json.dumps(L,ensure_ascii=False,indent=2))
print(f'{len(P)} paragraphs, {len(T)} question pages, {len(set(t["group"] for t in T))} groups, {len(words)} vocabulary entries')
